"""Checkpoint remaining convention reviews using the inspected source evidence."""
import runpy
from pathlib import Path
r = runpy.run_path(str(Path(__file__).with_name('AUDIT.review.py')))
load, checkpoint = r['load'], r['checkpoint']
inv = load('AUDIT.inventory.json')
code = [f['path'] for f in inv if f['path'].endswith('.cs') and not f['generated']]
lib = [p for p in code if p.startswith('src/')]
tests = [p for p in code if p.startswith('test/Xtate.IoC.Test/')]
docs = [f['path'] for f in inv if f['role'] == 'documentation']
checks = load('AUDIT.checks.json')
checkpoint('C01',lib+['README.md','docs/lifecycle.md'],'Compared type/argument keys, Empty alias, lifetime mappings and guide terminology. Sharing and ownership remain separate; external/forwarding entries do not register ownership. Resource argument identity is retained. Evidence: all library declarations in AUDIT.structure.json, api_families/resource_calls in AUDIT.checks.json, C13/C21 runtime traces.')
checkpoint('C02',lib,'Compared all library type declarations by immediate responsibility: I-prefixed interfaces, ImplementationEntry/FactoryProvider/Extensions families and foundational helper roles. Owner types publish to disposal bins; non-owner variants do not. Nested Provider/cache types preserve their documented role; no universal Service suffix applied.')
checkpoint('C03',lib,'Inspected signatures and full Arg0-4 API matrices in AUDIT.checks.json: unsuffixed ValueTask resolution, Sync counterparts, framework DisposeAsync/InitializeAsync names, Add/Get/Create and Is predicates match their roles. Preserved existing public names.')
checkpoint('C04',lib,'Compared field, parameter, local and generic names in structural signatures/bodies with immediate peers. Private instance fields use _camelCase; constants/static cache fields and public contract members use their role-specific forms. TArg, sp, tuple items and discards are intentional adapters, not rename candidates.')
checkpoint('C05',lib,'Traced count/index fields and parameters, DisposeToken, scope enums, Owner variants and argument arities against usage. Counts remain cardinalities; indexes select entries; sharing qualifiers do not imply ownership. No duration-valued public API requiring an invented unit convention found.')
ns_ex={x['path']:'Framework compatibility shim deliberately inhabits '+x['name']+' under target-framework guards; moving it would break the compatibility API. All configured library TFMs compile.' for x in checks['namespaces'] if x['name'].startswith('System')}
checkpoint('C06',code+['src/Xtate.IoC/Xtate.IoC.csproj.DotSettings','test/Xtate.IoC.Test/Xtate.IoC.Test.csproj.DotSettings','.github/instructions/examples.instructions.md'],'Compared every namespace to folder-skip settings and selected C06 policy: Xtate.IoC runtime, Xtate.IoC.Test tests, Xtate.IoC.Test.Examples scenarios; benchmark namespace retained. GlobalUsings/assembly attribute files need no namespace. IDE0130 ignores selected folder exceptions and is not a namespace migration requirement.',exceptions=ns_ex)
checkpoint('C07',[f['path'] for f in inv],'Compared the complete inventory paths and declared responsibilities with repository guide: runtime families, Tests, Examples, benchmark project, resources and build/configuration roots. No maintained component excluded by size; generated inputs retained as configuration evidence.')
checkpoint('C08',code,'Compared principal type names to file names using AUDIT.checks.json types and full declarations. Runtime files match principal types, including generic/partial families. Dedicated imports and metadata files have no principal runtime type; nested helpers and related scenario/benchmark collaborators are explicitly permitted by C08.')
checkpoint('C23',code,'AUDIT.members.json uses direct type spans, separating generic arities; no misplaced nested-type or instance-field ordering candidates remain. Reviewed matcher priorities and interface regions. Static fields are not alphabetized by the configured matcher; retain initialization order. Early public Provider classes match their special slot. AsyncEnumerable enumerator members and GenericLoggingExample ILog properties follow interface protocol groups; NUnit/xUnit layouts do not apply to MSTest.')
checkpoint('C24',lib,'Reviewed adjacent overloads, Arg0-4 extension blocks and completed/wait helper pairs against structural bodies. Interface regions and conditional-compilation groups remain together; fast-path fallbacks stay near their callers. No arbitrary global method alphabetization applied.')
checkpoint('C26',lib+['src/Xtate.IoC/Xtate.IoC.csproj'],'Reviewed explicit accessibility, overrides, public extension/container contracts and internal helpers against configured suggestion and InternalsVisibleTo. Public/protected implementation seams are compatibility contracts. Formatter emits no missing-accessibility diagnostic; all target compilations preserve legal interface/override visibility.')
checkpoint('C32',tests+['test/Xtate.IoC.Benchmark/*'],'Mapped all test and example classes to their subject/scenario folders, with separate benchmarks. AUDIT.checks.json enumerates 560 test methods; data cases produce 739 passing executions on each test TFM. Scenario Resolve names retain sufficient class context.')
checkpoint('C33',tests,'Read test method bodies and verified no-assert/catch candidates. No-throw smoke tests invoke the named operation; exception expectations use assertions, and concurrent disposal catches allow the documented race outcome then assert counts/handles. Async operations are awaited; method-level parallelism remains enabled. No Task-only restriction invented.')
checkpoint('C34',tests,'Inspected nested/local doubles, state counters, completion signals, using scopes and culture restoration. Related top-level example collaborators are permitted. Culture-changing tests restore in finally. Awaited fixture delays simulate work; bounded timeout delays guard hangs rather than asserting scheduling order.')
checkpoint('C35',tests,'Mapped runtime families to boundary tests: required/optional, arities, scope identity, ownership, initialization, decorators, failure/cancellation and disposal. Existing completed/pending diagnostic tests miss single-consumption IValueTaskSource factories; AUDIT.ValueTaskProbe.cs demonstrates that specific missing regression. Existing handle stress regression is retained, with deterministic race coverage required by CONS-018.',deviations={'test/Xtate.IoC.Test/Tests/ServiceProviderActionsTest.cs':['CONS-019']})
for cid in ['C36','C37']:
 checkpoint(cid,lib+['README.md','docs/lifecycle.md'],'Compared XML and implementation comments with signatures, owner-entry publication and lifecycle control flow. Shared README/lifecycle guide supplies repeated public semantics; unchanged declarations do not require a blanket XML retrofit. ObjectsBin claims universal concurrency/atomic exactly-once disposal and stack storage contrary to its implementation and selected lifecycle policy; CONS-020 identifies exact comment repairs.',deviations={'src/Xtate.IoC/IoC/ObjectsBin.cs':['CONS-020']})
checkpoint('C38',docs+tests,'Checked central README, repository guide and path instructions against current API families and executable examples. README links the canonical conventions/TODO; maintained documentation local links resolve (AUDIT.checks.json links). Examples compile and execute on all five test frameworks; no empty per-folder guides needed.')
checkpoint('C39',code+['.editorconfig','Xtate.IoC.sln.DotSettings'],'All maintained C# files retain AGPL headers and tab indentation. Reviewed explicit spacing/newline settings against source and formatter candidates. Formatter WHITESPACE includes unselected line-ending and JetBrains alignment/unary-spacing differences; no universal encoding/line-ending requirement inferred. Preserved single-line blocks are explicitly allowed. Generated/vendor formatter results are outside style scope.')
checkpoint('C40',code,'Compared all global/local using directives and aliases with System-first alphabetical import policy. Specialty imports remain local; Empty/NotNullAttribute aliases retain their meaning. Formatter IMPORTS flags exactly the two global lists; no broad namespace or alias rewrite required.',deviations={'src/Xtate.IoC/Properties/GlobalUsings.cs':['CONS-021'],'test/Xtate.IoC.Test/GlobalUsings.cs':['CONS-021']})
checkpoint('C41',code+['Directory.Build.props'],'Checked configured suggestion-level var/default/tuple/object-initializer/keyword/qualification forms against syntax and semantic roles. Read-only formatter has no diagnostics for these selected preferences; unrelated SDK suggestions do not become mandatory modernization. Preview syntax compiles for all six library TFMs with guarded compatibility APIs; no runtime API requirement inferred from language syntax.')
checkpoint('C43',code+['*.props','*.csproj'],'AUDIT.projects.json confirms analyzers/style and library warnings-as-errors; inspected all suppression sites in AUDIT.checks.json. No blanket ReSharper disable All remains. Existing fixture/cache/shim suppressions retain role rationale; two new examples have unexplained broad scopes. ReSharper CLI was unavailable: original replacement verification remains an explicit CONS-017 implementation acceptance step, not a claimed successful tool run. This source audit checks scope/rationale and configuration.',deviations={'test/Xtate.IoC.Test/Examples/DocumentationFeaturesExample.cs':['CONS-017'],'test/Xtate.IoC.Test/Examples/DocumentationJobExample.cs':['CONS-017']})
checkpoint('C49',tests+['test/Xtate.IoC.Benchmark/*','src/Xtate.IoC/Helpers/ResourcesExtensions.cs'],'Reviewed every timing/culture occurrence in AUDIT.checks.json: culture changes restore in finally; localization uses UI culture intentionally. Delays simulate awaited initialization or bound completion-signal waits, not race assertions. Threaded stress tests join workers; benchmarks keep setup separate and contain no randomized/logging/I/O measurement workload. No invariant-culture or clock-service retrofit required.')
